-- 스토어프론트 카탈로그 시드.
--
-- 기존 상품 1~3 은 id 와 price 를 그대로 둔다 — k6 부하 스크립트가 productId=1 을 쓰고,
-- 통합 테스트가 시드 상품을 전제한다. 이름만 실제 상품처럼 바꾸고 카테고리·설명을 채운다.


update products set
    name = 'USB-C 고속 충전 케이블', price = 10000,
    category_code = 'digital', brand = '볼트', featured = 0,
    description = '100W PD 충전을 지원하는 2m 케이블. 노트북과 스마트폰을 함께 충전한다.',
    image_url = 'https://picsum.photos/seed/1/600/600', created_at = '2026-06-01 10:00:00'
where product_id = 1;

update products set
    name = '친환경 대나무 칫솔 4종 세트', price = 5000,
    category_code = 'living', brand = '퓨어', featured = 0,
    description = '대나무 손잡이와 부드러운 미세모. 4개 한 세트로 오래 쓴다.',
    image_url = 'https://picsum.photos/seed/2/600/600', created_at = '2026-06-01 10:00:00'
where product_id = 2;

update products set
    name = '한정판 아로마 캔들 세트', price = 30000,
    category_code = 'living', brand = '루멘', featured = 0,
    description = '소이 원료로 만든 향초 3종. 한정 수량으로만 판매한다.',
    image_url = 'https://picsum.photos/seed/3/600/600', created_at = '2026-06-01 10:00:00'
where product_id = 3;


-- 25번은 품절(재고 0) — 스토어프론트의 품절 표시를 실제 상태로 확인하기 위한 시드다.
